settings.custom_liquid:
{% comment %} 
  ZINTEGROWANE LINKI DLA ROUTINES BY ALKMIE
{% endcomment %}
{% assign naglowek = "ZNAJDŹ NAS NA:" %}
{% assign link_tiktok = "https://www.tiktok.com/@routines_byalkmie" %}
{% assign handle_tiktok = "@routines_byalkmie" %}

{% assign link_instagram = "https://www.instagram.com/routines_byalkmie" %}
{% assign handle_instagram = "@routines_byalkmie" %}

{% comment %} USTAWIENIA WYGLĄDU {% endcomment %}
{% assign kolor_tekstu = "#000000" %}
{% assign kolor_neonu = "#b6ff51" %}
{% assign kolor_tla = "#ffffff" %}
{% assign margines_desktop = "50px" %}
{% assign margines_mobile = "30px" %}

<style>
  /* --- BAZA SEKCOJI --- */
  .custom-social-section {
    padding: {{ margines_desktop }} 0;
    text-align: center;
    background-color: {{ kolor_tla }};
    width: 100%;
    overflow: hidden;
  }

  .custom-social-section .social-heading {
    font-family: 'Barlow', sans-serif;
    font-size: 27px;
    font-weight: 700;
    font-style: normal;
    line-height: 1.0; 
    letter-spacing: 0px;
    text-transform: uppercase;
    margin: 0 auto 32px auto;
    color: {{ kolor_tekstu }};
    display: block;
  }

  .custom-social-section .social-icons-container {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 28px;
    margin-bottom: 16px;
  }

  /* --- EFEKTY WOW DLA IKON --- */
  .custom-social-section .social-icon-link {
    display: inline-block;
    position: relative;
    border-radius: 50%;
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.3s ease;
  }

  /* Efekt uniesienia i neonowego rozbłysku */
  .custom-social-section .social-icon-link:hover {
    transform: scale(1.15) translateY(-6px);
    box-shadow: 0 10px 25px {{ kolor_neonu | color_modify: 'alpha', 0.6 }}, 0 0 12px {{ kolor_neonu }};
  }

  .custom-social-section .social-icon-img {
    display: block;
    width: 70px;
    height: auto;
    object-fit: contain;
    border-radius: 50%;
  }

  /* --- DYNAMICZNE NAZWY PROFILI (HANDLES) --- */
  .custom-social-section .social-handles-driver {
    position: relative;
    height: 24px;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .custom-social-section .handle-text {
    font-family: 'Barlow', sans-serif;
    font-size: 16px;
    font-weight: 700;
    color: {{ kolor_tekstu }};
    position: absolute;
    opacity: 0;
    transform: translateY(10px);
    transition: transform 0.3s ease, opacity 0.3s ease;
    letter-spacing: 0.5px;
  }

  /* Aktywacja tekstu w zależności od najechania na ikonę */
  .custom-social-section:has(.js-tiktok:hover) .handle-tiktok {
    opacity: 1;
    transform: translateY(0);
  }

  .custom-social-section:has(.js-instagram:hover) .handle-instagram {
    opacity: 1;
    transform: translateY(0);
  }

  /* --- RESPONSIVNOŚĆ (MOBILE) --- */
  @media screen and (max-width: 749px) {
    .custom-social-section {
      padding: {{ margines_mobile }} 0;
    }

    .custom-social-section .social-heading {
      font-size: 18px;
      margin-bottom: 24px;
    }

    .custom-social-section .social-icon-img {
      width: 60px;
    }

    .custom-social-section .social-icons-container {
      gap: 20px;
    }

    .custom-social-section .handle-text {
      font-size: 14px;
    }
  }
</style>

<div class="custom-social-section">
  {%- if naglowek != blank -%}
    <h2 class="social-heading">{{ naglowek }}</h2>
  {%- endif -%}

  <div class="social-icons-container">
    {%- if link_tiktok != blank -%}
      <a href="{{ link_tiktok }}" class="social-icon-link js-tiktok" target="_blank" rel="noopener" aria-label="TikTok">
        <img src="https://cdn.shopify.com/s/files/1/0894/7908/6413/files/tiktok_1_4f6f8a1d-528a-405d-a05b-c7526d4f7f08.png?v=1782369947" alt="TikTok" class="social-icon-img" loading="lazy" width="70" height="70">
      </a>
    {%- endif -%}

    {%- if link_instagram != blank -%}
      <a href="{{ link_instagram }}" class="social-icon-link js-instagram" target="_blank" rel="noopener" aria-label="Instagram">
        <img src="https://cdn.shopify.com/s/files/1/0894/7908/6413/files/Group_5_4.png?v=1782369946" alt="Instagram" class="social-icon-img" loading="lazy" width="70" height="70">
      </a>
    {%- endif -%}
  </div>

  <div class="social-handles-driver">
    {%- if handle_tiktok != blank -%}
      <span class="handle-text handle-tiktok">{{ handle_tiktok }}</span>
    {%- endif -%}
    {%- if handle_instagram != blank -%}
      <span class="handle-text handle-instagram">{{ handle_instagram }}</span>
    {%- endif -%}
  </div>
</div>
